// Client-side-only convenience lock (edits never leave the browser). Password stored as
// SHA-256 hash — never plaintext.
var ADMIN_HASH='da28719dfd9c4da81f433d4788c3d0e10d97180018d0e32b65c967c45661597e';
async function sha256hex(s){try{var b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,'0')).join('')}catch(e){return ''}}
async function login(){var p=document.getElementById('aPass').value;if(await sha256hex(p)===ADMIN_HASH){enterEdit();document.getElementById('aPass').value=''}else{document.getElementById('aErr').textContent='Wrong password'}}
